export const DEFAULT_ADJUSTMENT=Object.freeze({brightness:100,contrast:100,saturation:100});
export function normalizeAdjustment(value={}){const bounded=(n)=>Math.min(150,Math.max(50,Number.isFinite(Number(n))?Number(n):100));return {brightness:bounded(value.brightness??100),contrast:bounded(value.contrast??100),saturation:bounded(value.saturation??100)};}
export function adjustPixels(data,value){const {brightness,contrast,saturation}=normalizeAdjustment(value);if(brightness===100&&contrast===100&&saturation===100)return data;const b=brightness/100,c=contrast/100,s=saturation/100;for(let i=0;i<data.length;i+=4){if(!data[i+3])continue;let r=((data[i]-128)*c+128)*b,g=((data[i+1]-128)*c+128)*b,blue=((data[i+2]-128)*c+128)*b;const gray=.2126*r+.7152*g+.0722*blue;data[i]=Math.max(0,Math.min(255,gray+(r-gray)*s));data[i+1]=Math.max(0,Math.min(255,gray+(g-gray)*s));data[i+2]=Math.max(0,Math.min(255,gray+(blue-gray)*s));}return data;}
export function adjustedImage(asset,value,source=false){const settings=normalizeAdjustment(value);if(Object.values(settings).every(n=>n===100))return source?asset.source:asset.image;const image=source?asset.source:asset.image;if(!image)return image;const key=(source?'source:':'cutout:')+Object.values(settings).join(',');if(asset.adjustCache?.key===key&&asset.adjustCache.image===image)return asset.adjustCache.canvas;const canvas=document.createElement('canvas');canvas.width=source?(image.naturalWidth||image.width):asset.w;canvas.height=source?(image.naturalHeight||image.height):asset.h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);adjustPixels(pixels.data,settings);ctx.putImageData(pixels,0,0);asset.adjustCache={key,canvas,image};return canvas;}
